set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

HELM_TMP=""
RENDER_TMP=""
CAPNICO_TMP=""

# cleanup_tmp removes the render and helm temp dirs, then hands the exit code
# on to lib.sh's on_exit.
cleanup_tmp() {
  local rc=$?
  rm -rf "${HELM_TMP}" "${RENDER_TMP}" "${CAPNICO_TMP}"
  return "${rc}"
}

stage_run() {
  require_cmd kubectl helm python3
  [[ -n "${DRY_RUN}" || -f "${OUT_DIR}/bootstrap-config.json" ]] ||
    die "${OUT_DIR}/bootstrap-config.json not found. Run 03-describe-site.sh first."
  helm_want="$(sed -n 's/^HELM_VERSION[[:space:]]*?*=[[:space:]]*//p' "${SBOM_DIR}/../../make/tool-versions.mk")"
  helm_have="$(helm version --template '{{.Version}}' 2>/dev/null || true)"
  [[ -z "${helm_want}" || "${helm_have}" == "${helm_want}" ]] ||
    warn "helm on PATH is ${helm_have:-unknown}; the repository pins ${helm_want} (make/tool-versions.mk)"
  trap 'cleanup_tmp; on_exit' EXIT

  # doc-begin
  # Imported images are eligible for kubelet garbage collection. Confirm they
  # are still present before anything schedules.
  if [[ -x "${INSTALL_DIR}/02-stage-images.sh" ]]; then
    "${INSTALL_DIR}/02-stage-images.sh" check ||
      die "staged images are missing. Rerun 02-stage-images.sh."
  fi

  HELM_TMP="$(mktemp -d "${TMPDIR:-/tmp}/nke-helm.XXXXXX")"

  # item nke-base-config (template)
  RENDER_TMP="$(mktemp -d "${TMPDIR:-/tmp}/nke-render.XXXXXX")"
  run python3 "${SBOM_DIR}/../../build/render-template.py" "${OUT_DIR}/bootstrap-config.json" "${SBOM_DIR}/nke-sbom/nke-base-config" "${RENDER_TMP}"
  for file in "${RENDER_TMP}"/*.yaml; do
    kc apply --server-side -f "${file}"
  done
  rm -rf "${RENDER_TMP}"

  # item spire-tpm-pubhashes (manifest)
  kc apply --server-side -f "${SBOM_DIR}/nke-sbom/spire-tpm-pubhashes/spire-tpm-pubhashes.yaml"

  # item spire-server-nodeport (manifest)
  kc apply --server-side -f "${SBOM_DIR}/nke-sbom/spire-server-nodeport/spire-server-nodeport.yaml"

  # item spire-oidc-provider-nodeport (manifest)
  kc apply --server-side -f "${SBOM_DIR}/nke-sbom/spire-oidc-provider-nodeport/spire-oidc-provider-nodeport.yaml"

  # item capnico (manifest)
  if [[ -n "${CAPNICO_IMAGE:-}" ]]; then
    CAPNICO_TMP="$(mktemp -d "${TMPDIR:-/tmp}/nke-capnico.XXXXXX")"
    cp "${SBOM_DIR}/nke-sbom/capnico/capnico.yaml" "${CAPNICO_TMP}/capnico.yaml"
    printf 'resources: [capnico.yaml]\nimages:\n  - name: %s\n    newName: %s\n    newTag: %s\n' \
      'ghcr.io/dsx-ai-factory/cluster-api-provider-nico/controller' "${CAPNICO_IMAGE%:*}" "${CAPNICO_IMAGE##*:}" >"${CAPNICO_TMP}/kustomization.yaml"
    run kubectl kustomize "${CAPNICO_TMP}" | kc apply --server-side -f -
    rm -rf "${CAPNICO_TMP}"
  else
    kc apply --server-side -f "${SBOM_DIR}/nke-sbom/capnico/capnico.yaml"
  fi

  # item nktp (helm)

  # building chart dependencies of ${SBOM_DIR}/nke-sbom/../../../nktp/deploy/charts/nktp
  run env HELM_REPOSITORY_CONFIG="${HELM_TMP}/repositories.yaml" HELM_REPOSITORY_CACHE="${HELM_TMP}/cache" helm repo add dependency-1 https://kubernetes-sigs.github.io/metrics-server/
  run env HELM_REPOSITORY_CONFIG="${HELM_TMP}/repositories.yaml" HELM_REPOSITORY_CACHE="${HELM_TMP}/cache" helm repo add dependency-2 https://open-telemetry.github.io/opentelemetry-helm-charts
  run env HELM_REPOSITORY_CONFIG="${HELM_TMP}/repositories.yaml" HELM_REPOSITORY_CACHE="${HELM_TMP}/cache" helm repo add dependency-3 https://prometheus-community.github.io/helm-charts
  run env HELM_REPOSITORY_CONFIG="${HELM_TMP}/repositories.yaml" HELM_REPOSITORY_CACHE="${HELM_TMP}/cache" helm dependency build "${SBOM_DIR}/nke-sbom/../../../nktp/deploy/charts/nktp" --skip-refresh

  # nktp -> release nktp (nktp 0.1.0-rc.2) in nktp
  hl upgrade --install nktp "${SBOM_DIR}/nke-sbom/../../../nktp/deploy/charts/nktp" --namespace nktp --wait --timeout "${PHASE_TIMEOUT:-15m}" --values "${SBOM_DIR}/nke-sbom/nktp/values.yaml"

  # item postgresql (helm)

  # postgresql -> release postgres (postgresql 18.5.15) in postgres
  hl upgrade --install postgres oci://registry-1.docker.io/bitnamicharts/postgresql --version 18.5.15 --namespace postgres --wait --timeout "${PHASE_TIMEOUT:-15m}" --values "${SBOM_DIR}/nke-sbom/postgresql/values.yaml"

  # item spire-crds (helm)

  # spire-crds -> release spire-crds (spire-crds 0.6.1) in spire-server
  hl upgrade --install spire-crds spire-crds --repo https://spiffe.github.io/helm-charts-hardened/ --version 0.6.1 --namespace spire-server --wait --timeout "${PHASE_TIMEOUT:-15m}"

  # item temporal (helm)

  # temporal -> release temporal (temporal 0.74.0) in temporal
  hl upgrade --install temporal temporal --repo https://go.temporal.io/helm-charts --version 0.74.0 --namespace temporal --wait --timeout "${PHASE_TIMEOUT:-15m}" --values "${SBOM_DIR}/nke-sbom/temporal/values.yaml" --values "${SBOM_DIR}/nke-sbom/temporal/overlay.yaml"

  # item spire (helm)

  # waiting for certificate/oidc-provider-upstream-ca condition=Ready
  kc -n spire-server get certificate/oidc-provider-upstream-ca >/dev/null 2>&1 ||
    die "phase spire requires certificate/oidc-provider-upstream-ca in namespace spire-server, which does not exist.
It is not part of this chart -- an earlier item supplies it. In this repository
that is the nke-base-config item, from ${SBOM_DIR}/k8s/oidc-upstream-ca.yaml."
  kc -n spire-server wait --for=condition=Ready certificate/oidc-provider-upstream-ca --timeout="${REQUIRE_TIMEOUT:-180s}"

  # spire -> release spire (spire 0.30.1) in spire-server
  hl upgrade --install spire spire --repo https://spiffe.github.io/helm-charts-hardened/ --version 0.30.1 --namespace spire-server --wait --timeout "${PHASE_TIMEOUT:-15m}" --values "${SBOM_DIR}/nke-sbom/spire/values.yaml" --values "${SBOM_DIR}/nke-sbom/spire/overlay.yaml"

  # item controller (helm)

  # controller -> release controller (nke-controller 0.0.0) in cloud-workflow-engine
  hl upgrade --install controller "${SBOM_DIR}/nke-sbom/../charts/controller" --namespace cloud-workflow-engine --wait --timeout "${PHASE_TIMEOUT:-15m}" --values "${SBOM_DIR}/nke-sbom/controller/values.yaml" --values "${SBOM_DIR}/nke-sbom/controller/overlay.yaml"
  # doc-end
}

stage_check() {
  log "provider"
  for crd in nicoclusters.infrastructure.cluster.x-k8s.io nicoclustertemplates.infrastructure.cluster.x-k8s.io nicomachines.infrastructure.cluster.x-k8s.io nicomachinetemplates.infrastructure.cluster.x-k8s.io; do
    if [[ "$(kc get crd "${crd}" -o jsonpath='{.status.conditions[?(@.type=="Established")].status}' 2>/dev/null)" == "True" ]]; then
      check_pass "CRD ${crd} Established"
    else
      check_fail "CRD ${crd} not Established"
    fi
  done
  if [[ "$(kc -n capnico-system get deployment controller-manager -o jsonpath='{.status.conditions[?(@.type=="Available")].status}' 2>/dev/null)" == "True" ]]; then
    check_pass "Deployment capnico-system/controller-manager Available"
  else
    check_fail "Deployment capnico-system/controller-manager not Available"
  fi
  if kc -n capnico-system get secret nico-credentials >/dev/null 2>&1; then
    check_pass "Secret capnico-system/nico-credentials present"
  else
    check_fail "Secret capnico-system/nico-credentials missing"
  fi
  if kc -n capnico-system get secret ghcr-imagepull >/dev/null 2>&1; then
    check_pass "Secret capnico-system/ghcr-imagepull present"
  else
    check_fail "Secret capnico-system/ghcr-imagepull missing"
  fi
  if kc -n cloud-workflow-engine get secret dgxc-tenant-credentials >/dev/null 2>&1; then
    check_pass "Secret cloud-workflow-engine/dgxc-tenant-credentials present"
  else
    check_fail "Secret cloud-workflow-engine/dgxc-tenant-credentials missing"
  fi

  log "plane"
  # Every release must be deployed. A failed release recovers by rerunning this
  # stage. A pending release needs `helm uninstall` first.
  releases="$(hl list -A -o json 2>/dev/null |
    python3 -c 'import json, sys; [print(r["name"], r["namespace"], r["status"]) for r in json.load(sys.stdin)]' 2>/dev/null || true)"
  while read -r name ns status; do
    [[ -n "${name}" ]] || continue
    case "${status}" in
    deployed) check_pass "helm release ${ns}/${name} deployed" ;;
    failed) check_fail "helm release ${ns}/${name} is failed: rerun this stage" ;;
    pending-*) check_fail "helm release ${ns}/${name} is ${status}: helm uninstall ${name} -n ${ns}, then rerun this stage" ;;
    *) check_fail "helm release ${ns}/${name} is ${status}" ;;
    esac
  done <<<"${releases}"
  for want in "nktp nktp" "postgres postgres" "spire-crds spire-server" "temporal temporal" "spire spire-server" "controller cloud-workflow-engine"; do
    set -- ${want}
    if ! printf '%s\n' "${releases}" | awk -v n="$1" -v s="$2" '$1 == n && $2 == s { found = 1 } END { exit !found }'; then
      check_fail "helm release $2/$1 missing: rerun this stage"
    fi
  done
  if [[ "$(kc -n cloud-workflow-engine get deployment cloud-workflow-engine -o jsonpath='{.status.conditions[?(@.type=="Available")].status}' 2>/dev/null)" == "True" ]]; then
    check_pass "Deployment cloud-workflow-engine/cloud-workflow-engine Available"
  else
    check_fail "Deployment cloud-workflow-engine/cloud-workflow-engine not Available"
  fi
  # /readyz reports the database and Temporal checks. The image ships curl.
  body="$(kc -n cloud-workflow-engine exec deploy/cloud-workflow-engine -- curl -sS -m 5 http://127.0.0.1:8080/readyz 2>/dev/null || true)"
  if printf '%s' "${body}" | python3 -c 'import json, sys; r = json.load(sys.stdin); c = r.get("checks", {}); sys.exit(0 if r.get("status") == "ok" and c.get("database") == "ok" and c.get("temporal") == "ok" else 1)' 2>/dev/null; then
    check_pass "/readyz: database ok, temporal ok"
  else
    check_fail "/readyz: ${body:-no response}"
  fi
  # The worker reads the NicoMachine CRD once at start. If it started before
  # CAPNICo, it skipped the NICo controllers and must be restarted.
  if kc -n cloud-workflow-engine logs deploy/cloud-workflow-engine --all-containers --tail=-1 2>/dev/null | grep -qF 'NicoMachine CRD not installed'; then
    check_fail "cloud-workflow-engine logged 'NicoMachine CRD not installed': kubectl -n cloud-workflow-engine rollout restart deployment/cloud-workflow-engine"
  else
    check_pass "cloud-workflow-engine log has no 'NicoMachine CRD not installed'"
  fi
}

stage_main "$@"
